/**
 * The app, in Spanish.
 *
 * Keyed on the ENGLISH source string, exactly as the German, French and Polish
 * tables are, because that is what ui() is handed at the call site. One
 * character out and the lookup misses in silence: the app draws the English and
 * nothing anywhere reports a problem.
 *
 * SCOPE. The whole interface, not the shell. This began as the navigation, the
 * home screen and the settings panels, with the strings inside lessons and the
 * trackers falling back to English — a stated scope rather than a silent gap.
 * That scope is met: check-interface-coverage has held Spanish to every string
 * the app asks for since its exemption was dropped, and the names of the
 * lessons arrived with the rest of the tables.
 *
 * ADDRESS. Tú throughout, never usted, matching the German table's du and the
 * English source's plain second person — this is an app that talks to one
 * person who chose to be here, not a form. Latin American readers get "tú" as
 * well; "vos" would exclude more people than it includes.
 */
