  "A shorter wording people use. Typing either one is accepted.": "Una forma más corta que usa la gente. Se acepta cualquiera de las dos.",
  "Shorter, and fine to type": "Más corta, y vale escribirla",
  "The same words. Only the spoken ending differs, and both are accepted.": "Las mismas palabras. Solo cambia la terminación hablada, y se aceptan las dos.",
  "Complete standard form": "Forma estándar completa",
  "Written out (same words)": "Escrito entero (las mismas palabras)",
  "Full version": "Versión completa",
