  "Stage numbers use Ctrl so Windows Alt-codes keep working. Hold Alt while typing the number-pad code, then release it. Arrow keys never take over an answer box.": "Los números de fase usan Ctrl para que los códigos Alt de Windows sigan funcionando. Mantén Alt mientras escribes el código en el teclado numérico y luego suéltalo. Las flechas nunca se apoderan de una casilla de respuesta.",
  "Need help?": "¿Necesitas ayuda?",
