  "Select": "Seleccionar",
  "Play {language} audio": "Reproducir el audio en {language}",
  "Graded in Listen mode — exposure only, not mastery.": "Calificado en modo escucha: solo exposición, no dominio.",
  "Known": "Sabido",
  "Struggle": "Difícil",
  "To learn": "Por aprender",
  "Memory strength": "Fuerza de memoria",
  "Click a bar to set it directly.": "Haz clic en una barra para fijarlo directamente.",
  "Come back in {days} day (level {level} of 5)": "Vuelve dentro de {days} día (nivel {level} de 5)",
  "Come back in {days} days (level {level} of 5)": "Vuelve dentro de {days} días (nivel {level} de 5)",
  "never reviewed again": "nunca se vuelve a repasar",
  "Its review is due today. Answer it once and it counts in full again, on a longer interval.": "Su repaso toca hoy. Respóndelo una vez y vuelve a contar entero, con un intervalo más largo.",
  "due for review": "toca repasarlo",
  "{days} days past its review, so you are assumed to still recall {kept}% of it — that is how much it counts towards your total right now. It halves every {halfLife} days towards {floor}% and never drops below that. Getting it right once puts it back to 100%.": "Han pasado {days} días desde su repaso, así que se supone que aún recuerdas el {kept} % — eso es lo que cuenta ahora para tu total. Se reduce a la mitad cada {halfLife} días hacia el {floor} % y nunca baja de ahí. Acertarlo una vez lo devuelve al 100 %.",
  "{days} days overdue · {kept}% remembered": "{days} días de retraso · {kept} % recordado",
  "review in": "repaso dentro de",
  "days short": "días menos",
  "How this count works": "Cómo funciona esta cuenta",
  "{count} item is fading right now.": "{count} elemento se está olvidando ahora mismo.",
  "{count} items are fading right now.": "{count} elementos se están olvidando ahora mismo.",
  "Show them": "Mostrarlos",
  "This number is an estimate of what you'd remember right now — not a tally of everything you have ever seen.": "Este número es una estimación de lo que recordarías ahora mismo, no un recuento de todo lo que has visto alguna vez.",
  "Something you learned recently counts as a whole item. Something you have not seen for a long time counts as less, because you probably remember less of it. That is why the number can go down as well as up.": "Algo que has aprendido hace poco cuenta como un elemento entero. Algo que llevas mucho sin ver cuenta menos, porque probablemente recuerdes menos. Por eso el número puede bajar además de subir.",
  "For example: you had “Guten Morgen” down two months ago and have not seen it since, so it counts as 0.8 rather than 1. Answer it correctly once and it counts fully again, immediately.": "Por ejemplo: te sabías «Guten Morgen» hace dos meses y no lo has vuelto a ver, así que cuenta 0,8 en vez de 1. Acértalo una vez y vuelve a contar entero, al instante.",
  "The more times you have recalled something correctly, the more slowly it slips. And nothing ever falls to zero — coming back to a word you once knew is far quicker than meeting it new.": "Cuantas más veces hayas recordado algo bien, más despacio se te escapa. Y nada llega nunca a cero: volver a una palabra que supiste es mucho más rápido que conocerla de nuevas.",
  "“Due” means today is its review day. “Fading” means that day has been and gone. Same items, just later — which is why a row shows one or the other, never both.": "«Toca repasarlo» significa que hoy es su día de repaso. «Olvidándose» significa que ese día ya pasó. Los mismos elementos, solo que más tarde, y por eso una fila muestra uno u otro, nunca los dos.",
  "Never fades: starred items, words you marked mastered by hand, and anything you learned outside the app — there is no review schedule to measure those against. This is the same number your dashboard, profile and games use.": "Nunca se olvidan: los elementos con estrella, las palabras que marcaste como dominadas a mano y todo lo aprendido fuera de la aplicación, porque no hay un calendario de repasos con el que medirlos. Es el mismo número que usan tu panel, tu perfil y los juegos.",
  "Word & sentence tracker": "Seguimiento de palabras y frases",
  "Loading your vocabulary catalog…": "Cargando tu catálogo de vocabulario…",
  "Review what you know, mark struggles, or reset items back to learn again.": "Repasa lo que sabes, marca lo difícil o devuelve elementos a por aprender.",
  "counting now": "cuentan ahora",
  "fading": "olvidándose",
  "due review": "repaso pendiente",
  "struggling": "cuesta",
