  "{target} or {meaning}…": "{target} o {meaning}…",
  "Most common first uses conversation usefulness, curriculum order, and then word frequency. Niche and extra-practice material stays later.": "Lo más común primero usa la utilidad en conversación, el orden del temario y luego la frecuencia de la palabra. El material especializado y de práctica extra se queda para después.",
  "Filters and sorting apply to the full tracker, not only the rows currently visible.": "Los filtros y la ordenación se aplican a todo el seguimiento, no solo a las filas que se ven ahora.",
