  "Add a card": "Añadir una tarjeta",
  "Paste a list": "Pegar una lista",
  "One card per line. Separate the two sides with a tab, a dash, an equals sign or a colon — a tab is what you get pasting two columns out of a spreadsheet.": "Una tarjeta por línea. Separa los dos lados con un tabulador, un guion, un signo igual o dos puntos; el tabulador es lo que sale al pegar dos columnas de una hoja de cálculo.",
  "Preview": "Vista previa",
  "no second side": "sin segundo lado",
  "more": "más",
  "Send this set to someone": "Enviar este conjunto a alguien",
  "Copy the text below and paste it into a message. Whoever receives it pastes it back in here — it is the same format the paste box already reads.": "Copia el texto de abajo y pégalo en un mensaje. Quien lo reciba lo pega aquí de vuelta: es el mismo formato que ya lee la casilla de pegar.",
  "Receive a set": "Recibir un conjunto",
  "Paste a shared set here to add its cards to this one. The title and description stay as they are.": "Pega aquí un conjunto compartido para añadir sus tarjetas a este. El título y la descripción se quedan como están.",
  "from": "de",
  "Stages": "Fases",
  "A Learn session walks each card up this ladder. Reorder or switch off whichever you like; what it takes to climb is set below.": "Una sesión de aprendizaje sube cada tarjeta por esta escalera. Reordena o desactiva las que quieras; lo que hace falta para subir se ajusta abajo.",
  "Remove stage": "Quitar la fase",
  "Add a stage": "Añadir una fase",
  "How the ladder is climbed": "Cómo se sube la escalera",
  "Right answers to promote": "Aciertos para subir",
  "How many in a row before a card moves up a stage. One is quick; four makes you prove it.": "Cuántos seguidos antes de que una tarjeta suba de fase. Uno es rápido; cuatro te lo hace demostrar.",
  "Cards per round": "Tarjetas por ronda",
  "How many a Learn session asks before it stops and shows you where you got to.": "Cuántas pregunta una sesión de aprendizaje antes de parar y enseñarte hasta dónde has llegado.",
  "A mistake costs a stage": "Un fallo cuesta una fase",
  "On: getting one wrong drops the card back down the ladder. Off: it only resets the streak, so a slip never undoes work.": "Activado: fallar una baja la tarjeta por la escalera. Desactivado: solo reinicia la racha, así que un desliz nunca deshace trabajo.",
