  "Import replaces this profile's saved data. Shared preferences and custom words also apply to this computer's local app. Other profiles are untouched. Continue?": "La importación sustituye los datos guardados de este perfil. Las preferencias compartidas y las palabras propias afectan también a la aplicación local de este ordenador. Los demás perfiles no se tocan. ¿Continuar?",
  "Downloaded languages": "Idiomas descargados",
  "A language downloads itself when you open its course. Remove one to get the space back — opening the course again brings it straight back.": "Un idioma se descarga solo al abrir su curso. Elimina uno para recuperar el espacio; al abrir el curso otra vez vuelve enseguida.",
