  "About languages: the German course is built into the program rather than installed separately, so there is nothing to uninstall that would save you space. The other languages are not here yet, and take up nothing.": "Sobre los idiomas: el curso de alemán viene dentro del programa en vez de instalarse aparte, así que no hay nada que desinstalar para ganar espacio. Los demás idiomas todavía no están aquí y no ocupan nada.",
  "Move your Micheon data": "Llévate tus datos de Micheon",
  "Take your progress, settings, custom words, mastery and installed pets to another computer with a private JSON file.": "Lleva tu progreso, tus ajustes, tus palabras propias, tu dominio y tus mascotas instaladas a otro ordenador con un archivo JSON privado.",
