  "Step {step}: {size} pairs, deeper in": "Paso {step}: {size} parejas, más adentro",
  "Nothing to match yet": "Todavía no hay nada que emparejar",
  "Once the course content is loaded, everything you are learning can be matched here.": "En cuanto se cargue el contenido del curso, todo lo que estás aprendiendo se podrá emparejar aquí.",
  "It remembers where you got to, so opening it again carries on rather than starting over — words and sentences each keep their own place, and the list comes back round for review when you reach the end. Tapping a card speaks it, at whatever volume you set for that language. Matching itself changes nothing — both answers are on screen, so it is recognition. Know it and the level menu do write, the same as anywhere else, and keep saying you know them deals bigger boards from further down the queue.": "Recuerda dónde te quedaste, así que al abrirlo otra vez continúa en vez de empezar de cero: las palabras y las frases guardan cada una su sitio, y la lista vuelve a dar la vuelta para repasar cuando llegas al final. Al tocar una tarjeta suena, al volumen que hayas puesto para ese idioma. Emparejar en sí no cambia nada: las dos respuestas están en pantalla, así que es reconocimiento. Lo sé y el menú de nivel sí escriben, igual que en cualquier otro sitio, y seguir diciendo que las sabes reparte tableros más grandes de más adelante en la cola.",
