  "A1 and A2 build the basics. B1 and B2 support independent conversation. C1 and C2 deepen precision, tone, and style.": "A1 y A2 construyen la base. B1 y B2 sostienen una conversación autónoma. C1 y C2 profundizan en precisión, tono y estilo.",
