  "Make everything bigger or smaller. Ctrl and + or - works anywhere, and Ctrl and 0 resets.": "Haz que todo se vea más grande o más pequeño. Ctrl y + o − funciona en cualquier sitio, y Ctrl y 0 lo restablece.",
  "Zoom out": "Alejar",
  "Zoom in": "Acercar",
  "Reset to 100%": "Volver al 100 %",
  "A small extension for Chrome, Edge and Brave that keeps teaching you while you browse: it highlights German words you already know on any page, quietly collects the ones it doesn't recognise (with the sentence they appeared in) so the word bank can grow from real usage, and switches YouTube to its German dub with English captions when a video has one.": "Una pequeña extensión para Chrome, Edge y Brave que te sigue enseñando mientras navegas: resalta en cualquier página las palabras alemanas que ya sabes, recoge sin ruido las que no reconoce (con la frase en la que aparecieron) para que el banco de palabras crezca con uso real, y pone YouTube en su doblaje alemán con subtítulos en inglés cuando el vídeo lo tiene.",
  "Included with this Micheon version": "Incluida con esta versión de Micheon",
  "Extension folder": "Carpeta de la extensión",
  "Highlights words you're learning, on any page": "Resalta las palabras que estás aprendiendo, en cualquier página",
  "Spots new words for the word bank, with real examples": "Detecta palabras nuevas para el banco de palabras, con ejemplos reales",
  "Auto-switches YouTube to its German dub + English captions": "Pone YouTube automáticamente en doblaje alemán + subtítulos en inglés",
  "Set up for": "Configurada para",
  "Set up the extension folder": "Preparar la carpeta de la extensión",
  "or download the .zip instead": "o descarga el .zip en su lugar",
  "Download the extension": "Descargar la extensión",
  "Couldn't set that up automatically — use the .zip download above instead.": "No se ha podido preparar automáticamente: usa la descarga del .zip de arriba.",
  "Micheon Immersion copied": "Micheon Immersion copiada",
  "updated from": "actualizada desde",
  "Your browser is opening. Its extensions-page address is already in your clipboard — paste it into the address bar": "Tu navegador se está abriendo. La dirección de su página de extensiones ya está en el portapapeles: pégala en la barra de direcciones",
  "then use Load unpacked for a first install, or click Reload on the existing Micheon Immersion card after an update. Refresh pages that were already open.": "y luego usa Cargar descomprimida para la primera instalación, o haz clic en Actualizar en la tarjeta de Micheon Immersion tras una actualización. Recarga las páginas que ya estuvieran abiertas.",
  "Folder opened — ready to load": "Carpeta abierta: lista para cargar",
  "Saved to": "Guardada en",
  "Installing it": "Cómo instalarla",
  "Not on the Chrome, Edge or Brave web store yet, so it installs the way any in-development extension does — no browser lets a download install itself, on purpose:": "Todavía no está en la tienda de Chrome, Edge ni Brave, así que se instala como cualquier extensión en desarrollo; ningún navegador deja que una descarga se instale sola, y es a propósito:",
  "Unzip the download somewhere it can stay (deleting the folder later removes the extension).": "Descomprime la descarga en un sitio donde pueda quedarse (si borras la carpeta luego, se quita la extensión).",
  "Open your browser's extensions page (type chrome://extensions, edge://extensions or brave://extensions into the address bar).": "Abre la página de extensiones de tu navegador (escribe chrome://extensions, edge://extensions o brave://extensions en la barra de direcciones).",
  "Turn on Developer mode.": "Activa el modo de desarrollador.",
  "For a first install, click “Load unpacked” and select the folder that just opened. After an app update, click Reload on the existing Micheon Immersion card instead.": "Para la primera instalación, haz clic en «Cargar descomprimida» y elige la carpeta que se acaba de abrir. Tras una actualización de la aplicación, haz clic en Actualizar en la tarjeta de Micheon Immersion.",
  "Click “Load unpacked” and select the unzipped folder.": "Haz clic en «Cargar descomprimida» y elige la carpeta descomprimida.",
  "Refresh browser pages that were already open so they use the new extension files.": "Recarga las páginas del navegador que ya estuvieran abiertas para que usen los archivos nuevos de la extensión.",
