  "Move your mouse to steer. Hold click or Space to boost speed (costs score). Eat words matching the Target Article to grow. Avoid hitting Bots! If a bot hits your body, you get bonus points.": "Mueve el ratón para dirigirte. Mantén el clic o Espacio para acelerar (cuesta puntos). Cómete las palabras que encajan con el artículo objetivo para crecer. ¡No choques con los bots! Si un bot choca con tu cuerpo, te llevas puntos extra.",
