  "Yes": "Sí",
  "No": "No",
  "Let's practise some German.": "Vamos a practicar un poco de alemán.",
  "Los geht's! Let's go.": "¡Los geht's! Vamos allá.",
  "German tip: when a word uses der, die, or das, learn them together — say “der Tisch”, not just “Tisch”.": "Consejo de alemán: cuando una palabra lleva der, die o das, apréndelos juntos: di «der Tisch», no solo «Tisch».",
  "German tip: in a normal German sentence, the verb comes second — “Heute gehe ich nach Hause.”": "Consejo de alemán: en una frase alemana normal, el verbo va en segundo lugar: «Heute gehe ich nach Hause».",
  "German tip: after weil or dass, put the verb at the end — “weil ich müde bin”.": "Consejo de alemán: después de weil o dass, el verbo va al final: «weil ich müde bin».",
  "German tip: German words for people, places, things, or ideas always start with a capital letter.": "Consejo de alemán: las palabras alemanas para personas, lugares, cosas o ideas siempre empiezan con mayúscula.",
  "German tip: some verbs split in two — “aufstehen” becomes “Ich stehe um sieben auf.”": "Consejo de alemán: algunos verbos se parten en dos: «aufstehen» se convierte en «Ich stehe um sieben auf».",
  "English tip: normal sentences usually put who or what first, then the action, then the rest — “I read the book.”": "Consejo de inglés: las frases normales suelen poner primero quién o qué, luego la acción y luego el resto: «I read the book».",
  "English tip: after can, must, should, or will, use the verb without “to” — “can go”, not “can to go”.": "Consejo de inglés: después de can, must, should o will, usa el verbo sin «to»: «can go», no «can to go».",
  "English tip: for habits or facts, verbs with he, she, or it usually end in -s — “she works”, “he knows”.": "Consejo de inglés: para hábitos o hechos, los verbos con he, she o it suelen acabar en -s: «she works», «he knows».",
  "English tip: describing words normally come before the thing — “a red car”. They stay the same — “a nice man”, “a nice woman”.": "Consejo de inglés: las palabras que describen van normalmente antes de la cosa: «a red car». No cambian: «a nice man», «a nice woman».",
  "English tip: choose “a” or “an” by sound, not spelling — “a university”, but “an hour”.": "Consejo de inglés: elige «a» o «an» por el sonido, no por la ortografía: «a university», pero «an hour».",
  "English tip: after “didn't”, use go, see, or do — not went, saw, or did: “I didn't go.”": "Consejo de inglés: después de «didn't», usa go, see o do, no went, saw ni did: «I didn't go».",
  "English tip: “cannot” is one word. Its short form is “can't”.": "Consejo de inglés: «cannot» es una sola palabra. Su forma corta es «can't».",
  "English tip: “will not” becomes “won't”, never “willn't”.": "Consejo de inglés: «will not» se convierte en «won't», nunca «willn't».",
  "English tip: German “es gibt” becomes “there is” for one thing and “there are” for several — never “it gives”.": "Consejo de inglés: el alemán «es gibt» se dice «there is» para una cosa y «there are» para varias, nunca «it gives».",
  "English tip: when talking about the past, use “there was” for one thing and “there were” for several.": "Consejo de inglés: al hablar del pasado, usa «there was» para una cosa y «there were» para varias.",
  "English tip: do not use two negatives together — “I didn't see anything”, not “I didn't see nothing”.": "Consejo de inglés: no uses dos negaciones juntas: «I didn't see anything», no «I didn't see nothing».",
  "English tip: “should not” becomes “shouldn't”. The same shortening gives “wouldn't”, “couldn't”, and “mustn't”.": "Consejo de inglés: «should not» se convierte en «shouldn't». La misma reducción da «wouldn't», «couldn't» y «mustn't».",
  "English tip: use “haven't” with I, you, we, or they, and “hasn't” with he, she, or it — “I haven't seen it yet”.": "Consejo de inglés: usa «haven't» con I, you, we o they, y «hasn't» con he, she o it: «I haven't seen it yet».",
