  "Learn every Windows numpad code for German letters, then practise the characters in real words and sentences. Includes laptop and no-numpad options.": "Aprende todos los códigos del teclado numérico de Windows para las letras alemanas y luego practica los caracteres en palabras y frases reales. Incluye opciones para portátil y sin teclado numérico.",
  "Num Lock on; hold the left Alt key, enter all four digits on the numeric keypad, then release Alt. The number row above the letters will not work. No numpad? Use Micheon's character buttons, or add US-International or UK Extended in Windows.": "Con Bloq Num activado, mantén pulsada la tecla Alt izquierda, escribe los cuatro dígitos en el teclado numérico y suelta Alt. La fila de números de arriba no funciona. ¿Sin teclado numérico? Usa los botones de caracteres de Micheon, o añade US-International o UK Extended en Windows.",
