  "Nothing brings it back today": "Hoy no lo trae nada de vuelta",
  "Held back until then": "Retenido hasta entonces",
  "Nothing will show this before then.": "Nada mostrará esto antes de esa fecha.",
  "Right now: {words} words + {sentences} sentences = {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Ahora mismo: {words} palabras + {sentences} frases = {total} tarjetas cada vez, cada una oída {passes}×. Las primeras {total} suenan {passes} veces y luego las {total} siguientes hacen lo mismo.",
  "Right now: {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Ahora mismo: {total} tarjetas cada vez, cada una oída {passes}×. Las primeras {total} suenan {passes} veces y luego las {total} siguientes hacen lo mismo.",
  "Words and sentences": "Palabras y frases",
  "Words only": "Solo palabras",
  "Sentences and phrases only": "Solo frases y expresiones",
  "Straight away": "De inmediato",
  "After a few hours": "Al cabo de unas horas",
  "After a day": "Al cabo de un día",
  "When the review says so": "Cuando lo diga el repaso",
  "No wait at all. Anything can play again the moment the order reaches it — which on a narrow filter can mean the same handful of cards all evening. Right for a first pass through a new pack, and not much else.": "Sin espera ninguna. Cualquier cosa puede volver a sonar en cuanto el orden llegue a ella, lo que con un filtro estrecho puede significar el mismo puñado de tarjetas toda la tarde. Está bien para una primera pasada por un paquete nuevo, y para poco más.",
  "About four hours. Long enough that you have to remember it rather than recognise it from a minute ago, and short enough to meet it again the same day.": "Unas cuatro horas. Bastante para que tengas que recordarlo en vez de reconocerlo de hace un minuto, y poco para volver a encontrártelo el mismo día.",
  "A full day. This is the shortest gap the review ladder ever asks for, and the point at which hearing something again is recall rather than an echo.": "Un día entero. Es el intervalo más corto que pide la escalera de repasos, y el punto en que volver a oír algo es recordarlo y no un eco.",
  "Nothing you have answered correctly comes back until the review ladder says it is due — one day, then three, ten, thirty, a hundred and eighty. Anything you have heard but never answered waits a day.": "Nada que hayas acertado vuelve hasta que la escalera de repasos diga que toca: un día, luego tres, diez, treinta, ciento ochenta. Lo que has oído pero nunca has respondido espera un día.",
