  "The pictures beside the words. Around eight hundred of them ship with the app, so they look the same on every machine and work with no connection.": "Las imágenes junto a las palabras. Unas ochocientas vienen con la aplicación, así que se ven igual en cualquier ordenador y funcionan sin conexión.",
  "Tatoeba": "Tatoeba",
  "Part of the real-sentence practice. Most of the course is written for Micheon, and the share coming from here falls with every pack that replaces it.": "Parte de la práctica con frases reales. La mayor parte del curso está escrita para Micheon, y la proporción que viene de aquí baja con cada paquete que la sustituye.",
  "Lucide": "Lucide",
  "The interface icons.": "Los iconos de la interfaz.",
  "Electron, React and Vite": "Electron, React y Vite",
  "What the desktop app is built with.": "Con lo que está hecha la aplicación de escritorio.",
  "Also stay over fullscreen games, watch-only — clicks pass straight through. Some machines still give the game up a frame for anything drawn over it.": "También se quedan sobre los juegos a pantalla completa, solo para mirar: los clics pasan de largo. Aun así, algunas máquinas le quitan al juego un fotograma por cualquier cosa dibujada encima.",
  "🌱 I'm new to coding": "🌱 Soy nuevo en programación",
  "colour, practise": "colour, practise",
  "color, practice": "color, practice",
  "Walks each card up the stages you set. The one that tracks progress.": "Sube cada tarjeta por las fases que fijes. Es la que registra el progreso.",
  "Flip through at your own pace. Nothing is graded.": "Pasa las tarjetas a tu ritmo. No se califica nada.",
  "Answer the whole set, then see a score and every correction.": "Responde el conjunto entero y luego mira la nota y todas las correcciones.",
  "Match": "Emparejar",
  "Pair terms against definitions, against the clock.": "Empareja términos con definiciones, contra el reloj.",
  "Builds the set into your memory. Progress only moves here.": "Fija el conjunto en tu memoria. El progreso solo avanza aquí.",
  "Checks where you stand. Graded, and it changes nothing.": "Comprueba cómo vas. Se califica, y no cambia nada.",
