  "Order": "Orden",
  "Levels": "Niveles",
  "Similar sentences together": "Frases parecidas juntas",
  "The course's pick": "La elección del curso",
  "How Continue learning is put together": "Cómo se arma Seguir aprendiendo",
  "The course's pick blends how common a sentence is with how hard it is and how far you are. Easiest first takes all of one level before the next. Most common first takes what people say most, whatever the level. Similar sentences together takes the next sentence and then every sentence that starts the same way — all the “Ich möchte …”, then all the “Kannst du …”. Conversation order takes an exchange as the dialogues have it — a question, then the answer that fits it, then what comes next. Shortest first and Longest first go by length. Reviews come back whatever the order.": "La elección del curso combina lo común que es una frase con su dificultad y lo lejos que has llegado. Lo más fácil primero toma todo un nivel antes del siguiente. Lo más común primero toma lo que más dice la gente, sea cual sea el nivel. Frases parecidas juntas toma la siguiente frase y luego todas las que empiezan igual: todas las “Ich möchte …”, luego todas las “Kannst du …”. Orden de conversación toma un intercambio tal como lo tienen los diálogos: una pregunta, luego la respuesta que encaja, luego lo que sigue. Lo más corto primero y Lo más largo primero van por longitud. Los repasos vuelven sea cual sea el orden.",
  "Order decides what comes first and still teaches everything. This decides what a sitting draws on at all, so you can work through one level and stop. Reviews are never held back.": "El orden decide qué va primero y aun así lo enseña todo. Esto decide de qué se nutre una sesión, así que puedes recorrer un nivel y parar. Los repasos nunca se retienen.",
  "Conversation order": "Orden de conversación",
  "Changing this rebuilds the sitting from the start.": "Cambiar esto vuelve a armar la sesión desde el principio.",

